-- Initial PostgreSQL migration. Prices are INTEGER centavos; timestamps stored UTC.
CREATE TYPE "StaffRole" AS ENUM ('STAFF','ADMIN');
CREATE TYPE "FulfillmentStatus" AS ENUM ('PENDING_PAYMENT','CONFIRMED','PREPARING','READY_FOR_PICKUP','COMPLETED','CANCELLED');
CREATE TYPE "PaymentStatus" AS ENUM ('UNPAID','PENDING','PAID','FAILED','REFUNDED','PARTIALLY_REFUNDED');
CREATE TYPE "PaymentMethod" AS ENUM ('GCASH','PAY_AT_PICKUP');
CREATE TYPE "ReservationStatus" AS ENUM ('ACTIVE','CONSUMED','RELEASED');
CREATE TYPE "NoticeKind" AS ENUM ('CONFIRMATION','PAYMENT_READY','READY','CANCELLED');
CREATE TYPE "NoticeChannel" AS ENUM ('EMAIL','PUSH');
CREATE TYPE "NoticeState" AS ENUM ('PENDING','SENDING','SENT','FAILED');
CREATE TABLE "StaffUser" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "StaffRole" NOT NULL DEFAULT 'STAFF',"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "StaffSession" ("id" TEXT PRIMARY KEY,"tokenHash" TEXT NOT NULL UNIQUE,"staffId" TEXT NOT NULL REFERENCES "StaffUser"("id") ON DELETE CASCADE ON UPDATE CASCADE,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "StaffSession_staffId_expiresAt_idx" ON "StaffSession"("staffId","expiresAt");
CREATE TABLE "RateLimit" ("key" TEXT PRIMARY KEY,"windowStart" TIMESTAMP(3) NOT NULL,"count" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "BusinessSettings" ("id" TEXT PRIMARY KEY DEFAULT 'main',"name" TEXT NOT NULL DEFAULT 'Kafe Lilim',"tagline" TEXT NOT NULL DEFAULT 'Your quiet corner, one cup at a time.',"description" TEXT NOT NULL DEFAULT 'A slow moment, made with care.',"heroImage" TEXT,"logoUrl" TEXT,"address" TEXT NOT NULL DEFAULT 'SAMPLE ADDRESS — add your actual café location before taking orders',"email" TEXT NOT NULL DEFAULT 'placeholder@example.com',"phone" TEXT NOT NULL DEFAULT 'Not configured',"openTime" TEXT NOT NULL DEFAULT '08:00',"closeTime" TEXT NOT NULL DEFAULT '20:00',"closedDates" JSONB NOT NULL DEFAULT '[]',"prepMinutes" INTEGER NOT NULL DEFAULT 30,"advanceOrdering" BOOLEAN NOT NULL DEFAULT true,"acceptOrders" BOOLEAN NOT NULL DEFAULT false,"pickupInstructions" TEXT NOT NULL DEFAULT 'Please collect your order at the café counter.',"socialUrl" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Category" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE,"sortOrder" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "MenuItem" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"priceCentavos" INTEGER NOT NULL,"imageUrl" TEXT,"categoryId" TEXT NOT NULL REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"featured" BOOLEAN NOT NULL DEFAULT false,"hidden" BOOLEAN NOT NULL DEFAULT false,"archived" BOOLEAN NOT NULL DEFAULT false,"available" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "MenuItem_categoryId_archived_hidden_idx" ON "MenuItem"("categoryId","archived","hidden");
CREATE TABLE "ModifierGroup" ("id" TEXT PRIMARY KEY,"itemId" TEXT NOT NULL REFERENCES "MenuItem"("id") ON DELETE CASCADE ON UPDATE CASCADE,"name" TEXT NOT NULL,"minSelect" INTEGER NOT NULL DEFAULT 0,"maxSelect" INTEGER NOT NULL DEFAULT 1,"sortOrder" INTEGER NOT NULL DEFAULT 0);
CREATE INDEX "ModifierGroup_itemId_idx" ON "ModifierGroup"("itemId");
CREATE TABLE "ModifierOption" ("id" TEXT PRIMARY KEY,"groupId" TEXT NOT NULL REFERENCES "ModifierGroup"("id") ON DELETE CASCADE ON UPDATE CASCADE,"name" TEXT NOT NULL,"priceCentavos" INTEGER NOT NULL DEFAULT 0,"available" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "Inventory" ("id" TEXT PRIMARY KEY,"itemId" TEXT NOT NULL UNIQUE REFERENCES "MenuItem"("id") ON DELETE CASCADE ON UPDATE CASCADE,"available" INTEGER NOT NULL DEFAULT 0,"reserved" INTEGER NOT NULL DEFAULT 0,"lowStockAt" INTEGER NOT NULL DEFAULT 5,"unlimited" BOOLEAN NOT NULL DEFAULT false,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Inventory_nonnegative" CHECK ("available" >= 0 AND "reserved" >= 0));
CREATE TABLE "InventoryMovement" ("id" TEXT PRIMARY KEY,"inventoryId" TEXT NOT NULL REFERENCES "Inventory"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"deltaAvailable" INTEGER NOT NULL DEFAULT 0,"deltaReserved" INTEGER NOT NULL DEFAULT 0,"reason" TEXT NOT NULL,"orderId" TEXT,"staffId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "InventoryMovement_inventoryId_createdAt_idx" ON "InventoryMovement"("inventoryId","createdAt");
CREATE TABLE "Order" ("id" TEXT PRIMARY KEY,"orderNumber" TEXT NOT NULL UNIQUE,"clientRequestId" TEXT NOT NULL UNIQUE,"trackingTokenHash" TEXT NOT NULL UNIQUE,"trackingTokenEncrypted" TEXT NOT NULL,"customerName" TEXT NOT NULL,"customerEmail" TEXT NOT NULL,"customerPhone" TEXT,"pickupAt" TIMESTAMP(3) NOT NULL,"instructions" TEXT,"fulfillmentStatus" "FulfillmentStatus" NOT NULL DEFAULT 'CONFIRMED',"paymentStatus" "PaymentStatus" NOT NULL DEFAULT 'UNPAID',"paymentMethod" "PaymentMethod" NOT NULL,"totalCentavos" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'PHP',"cancelReason" TEXT,"refundRequired" BOOLEAN NOT NULL DEFAULT false,"paidAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Order_positive_amount" CHECK ("totalCentavos">0));
CREATE INDEX "Order_createdAt_idx" ON "Order"("createdAt");
CREATE INDEX "Order_pickupAt_fulfillmentStatus_idx" ON "Order"("pickupAt","fulfillmentStatus");
CREATE INDEX "Order_paymentStatus_paidAt_idx" ON "Order"("paymentStatus","paidAt");
CREATE TABLE "OrderItem" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"originalItemId" TEXT NOT NULL,"name" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"unitCentavos" INTEGER NOT NULL,"modifiers" JSONB NOT NULL,"note" TEXT,"lineCentavos" INTEGER NOT NULL);
CREATE INDEX "OrderItem_orderId_idx" ON "OrderItem"("orderId");
CREATE TABLE "Payment" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"providerSessionId" TEXT UNIQUE,"providerPaymentId" TEXT UNIQUE,"checkoutUrl" TEXT,"amountCentavos" INTEGER NOT NULL,"status" "PaymentStatus" NOT NULL,"method" "PaymentMethod" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"collectedAt" TIMESTAMP(3));
CREATE INDEX "Payment_orderId_status_idx" ON "Payment"("orderId","status");
CREATE TABLE "PaymentEvent" ("id" TEXT PRIMARY KEY,"externalId" TEXT NOT NULL UNIQUE,"eventType" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "StockReservation" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"inventoryId" TEXT NOT NULL REFERENCES "Inventory"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"quantity" INTEGER NOT NULL,"status" "ReservationStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StockReservation_positive" CHECK ("quantity">0));
CREATE UNIQUE INDEX "StockReservation_orderId_inventoryId_key" ON "StockReservation"("orderId","inventoryId");
CREATE INDEX "StockReservation_status_createdAt_idx" ON "StockReservation"("status","createdAt");
CREATE TABLE "Notification" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"kind" "NoticeKind" NOT NULL,"channel" "NoticeChannel" NOT NULL,"state" "NoticeState" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"nextAttemptAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastError" TEXT,"deliveredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Notification_orderId_kind_channel_key" ON "Notification"("orderId","kind","channel");
CREATE INDEX "Notification_state_nextAttemptAt_idx" ON "Notification"("state","nextAttemptAt");
CREATE TABLE "PushSubscription" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"endpoint" TEXT NOT NULL UNIQUE,"p256dh" TEXT NOT NULL,"auth" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"staffId" TEXT NOT NULL REFERENCES "StaffUser"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"action" TEXT NOT NULL,"targetId" TEXT NOT NULL,"detail" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");

CREATE TYPE "RefundStatus" AS ENUM ('REQUESTED','PENDING','PROCESSING','SUCCEEDED','FAILED');
CREATE TABLE "Refund" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"paymentId" TEXT NOT NULL REFERENCES "Payment"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"providerRefundId" TEXT UNIQUE,"amountCentavos" INTEGER NOT NULL,"status" "RefundStatus" NOT NULL DEFAULT 'REQUESTED',"reason" TEXT NOT NULL,"staffId" TEXT NOT NULL,"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Refund_positive" CHECK ("amountCentavos">0));
CREATE INDEX "Refund_orderId_status_idx" ON "Refund"("orderId","status");
CREATE INDEX "Refund_completedAt_status_idx" ON "Refund"("completedAt","status");
